    {
      "subject": "F1 #2 on D3",
      "verdict": "confirmed",
      "reason": "Household 3, income $58,000 = 212.3% FPG (27320). Policy quote gives 90% discount for 201-250% FPG. D3 patient_balance 1490.25 with no discount applied. Math: 1490.25 * 0.9 = 1341.23. Quotes and case data support."
    },
    {
      "subject": "F2 #1 on D1",
      "verdict": "problem",
      "reason": "Deadline 2026-04-01 is based on '12 months after last insurance payment' but the case contains no last insurance payment date for this account. One-year-after-service (2025-01-06) and federal 240-day-after-first-bill (2025-04-05) deadlines have passed. The claimed 16 days left relies on an unsupported payment date."
    },
    {
      "subject": "letter itemized",
      "verdict": "confirmed",
      "reason": "Account 30955 with services 2024-11-25 to 2025-01-06 matches S12. Account 409798605 with services 2025-02-11 to 2025-02-13 matches D1/D2. Florida statute citation not verified but factual references are correct."
    },
    {
      "subject": "letter dispute",
      "verdict": "confirmed",
      "reason": "Account 44932556 (S10) lines 1-2 are duplicate code 01960 on 2025-02-11 at $4,944 each. S1 lines 5-6 show patient responsibility $196.82 for each duplicate. Letter accurately reflects the documents."
    },
    {
      "subject": "letter application",
      "verdict": "confirmed",
      "reason": "Household size 3, income $58,000, 212.3% FPG, 90% discount per policy. Deadline April 1, 2026 matches the deadline referenced in F2 (though that deadline itself is questionable, the letter's statement of intent is consistent with the case data)."
    }
